pub fn myfun(a: &mut Vec<i32>, b: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Convert N to usize for indexing
    let n = N as usize;

    // Overwrite every element of a and b with 1
    for i in 0..n {
        a[i] = 1;
        b[i] = 1;
    }

    // Initialize the single accumulator entry to 0
    // We assume `sum.len() == 1`
    sum[0] = 0;

    // Add the sum of all elements in a and b into the accumulator
    for i in 0..n {
        sum[0] += a[i] + b[i];
    }
}

